import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.Bja9t6Wf.js";const u=JSON.parse('{"title":"Part 4: The Widow, Politics, and the Rain of Gold","description":"","frontmatter":{},"headers":[],"relativePath":"en/oevp-spenden.md","filePath":"en/oevp-spenden.md"}'),r={name:"en/oevp-spenden.md"};function s(n,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="part-4-the-widow-politics-and-the-rain-of-gold" tabindex="-1">Part 4: The Widow, Politics, and the Rain of Gold <a class="header-anchor" href="#part-4-the-widow-politics-and-the-rain-of-gold" aria-label="Permalink to &quot;Part 4: The Widow, Politics, and the Rain of Gold&quot;">​</a></h1><p>In this section of our mockumentary, we dedicate ourselves to what is perhaps the most modern and simultaneously absurd phase: the relationship between Heidi Horten and the Austrian People&#39;s Party (ÖVP).</p><h2 id="the-art-of-splitting" tabindex="-1">The Art of Splitting <a class="header-anchor" href="#the-art-of-splitting" aria-label="Permalink to &quot;The Art of Splitting&quot;">​</a></h2><p>Our research (supported by the fictional expertise of Dr. von Zitzewitz) reveals a fascinating pattern: if you break a large donation into many small parts, it becomes virtually invisible to the naked eye of the Court of Audit. We call this the &quot;Horten Cloaking Effect.&quot;</p><h3 id="the-facts-satirically-processed" tabindex="-1">The Facts (Satirically Processed): <a class="header-anchor" href="#the-facts-satirically-processed" aria-label="Permalink to &quot;The Facts (Satirically Processed):&quot;">​</a></h3><ul><li><strong>The Motive:</strong> Pure altruism towards the political landscape.</li><li><strong>The Method:</strong> &quot;Pointillism of Capital&quot; – many small dots create a very large picture.</li><li><strong>The Reaction:</strong> Stunned politicians asserting that one should surely still be allowed to accept &quot;small tokens of appreciation.&quot;</li></ul><h2 id="the-justification-arias" tabindex="-1">The Justification Arias <a class="header-anchor" href="#the-justification-arias" aria-label="Permalink to &quot;The Justification Arias&quot;">​</a></h2><p>We are planning a montage of (acted) interviews with ÖVP officials trying to explain the donations.</p><blockquote><p><em>&quot;Mrs. Horten simply loves democracy. And democracy costs... postage. A lot of postage.&quot;</em></p></blockquote><hr><p><em>This part of the film will play particularly boldly with the boundaries between reality and satire.</em></p>',11)])])}const f=t(r,[["render",s]]);export{u as __pageData,f as default};
